// Application tables. The auth tables (user, session, account, verification,
// sso_provider) are generated by better-auth into auth-schema.ts.
//
// Rules the schema encodes (see IDEAS.md):
// - one skill entity org-wide; the TARGET varies by role / grade / person, never the skill
// - only leaf skills are rated (a skill with active sub-skills is a heading)
// - self and validated levels are two columns, never one overwritten by the other
// - "not assessed" is NULL, never 0
// - gaps, coverage and on-target % are computed, never stored
import {
  pgTable, text, integer, boolean, timestamp, date, jsonb, primaryKey, uniqueIndex, index, real,
} from "drizzle-orm/pg-core";
import { user } from "./auth-schema.ts";

export * from "./auth-schema.ts";

const id = () => text("id").primaryKey().$defaultFn(() => crypto.randomUUID());
const created = () => timestamp("created_at", { withTimezone: true }).defaultNow().notNull();

// ---- organisation ---------------------------------------------------------------

export const orgUnit = pgTable("org_unit", {
  id: id(),
  name: text("name").notNull(),
  // company | division | department | team (free text kept short; only used for labels)
  kind: text("kind").notNull().default("team"),
  parentId: text("parent_id"),
  managerId: text("manager_id"),
  sort: integer("sort").notNull().default(0),
  // set when the directory sync owns this unit ("mgr:<directory id>" - a manager's team)
  externalKey: text("external_key").unique(),
  createdAt: created(),
}, (t) => [index("org_unit_parent_idx").on(t.parentId)]);

export const jobRole = pgTable("job_role", {
  id: id(),
  name: text("name").notNull().unique(),
  description: text("description").notNull().default(""),
  createdAt: created(),
});

export const grade = pgTable("grade", {
  id: id(),
  name: text("name").notNull().unique(),
  rank: integer("rank").notNull().default(0),
});

export const employee = pgTable("employee", {
  id: id(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  title: text("title").notNull().default(""),
  unitId: text("unit_id").references(() => orgUnit.id, { onDelete: "set null" }),
  roleId: text("role_id").references(() => jobRole.id, { onDelete: "set null" }),
  gradeId: text("grade_id").references(() => grade.id, { onDelete: "set null" }),
  managerId: text("manager_id"),
  userId: text("user_id").references(() => user.id, { onDelete: "set null" }).unique(),
  location: text("location").notNull().default(""),
  active: boolean("active").notNull().default(true),
  // ---- from the user directory (ServiceNow sys_user) when the sync is in use
  /** manual (created here or by CSV) | directory (owned by the sync) */
  source: text("source").notNull().default("manual"),
  /** the directory's record id (sys_id) */
  externalId: text("external_id").unique(),
  /** the directory login name (user_name) */
  userName: text("user_name"),
  /** the value of the configured user-type field, e.g. human / machine */
  userType: text("user_type").notNull().default(""),
  /** every synced field, raw, for the photo URL template and the info panel */
  attributes: jsonb("attributes").$type<Record<string, string>>().notNull().default({}),
  syncedAt: timestamp("synced_at", { withTimezone: true }),
  createdAt: created(),
}, (t) => [index("employee_unit_idx").on(t.unitId), index("employee_manager_idx").on(t.managerId), index("employee_user_name_idx").on(t.userName),
  index("employee_role_idx").on(t.roleId), index("employee_grade_idx").on(t.gradeId)]);

// ---- taxonomy and proficiency ---------------------------------------------------

export const skillCategory = pgTable("skill_category", {
  id: id(),
  name: text("name").notNull().unique(),
  description: text("description").notNull().default(""),
  sort: integer("sort").notNull().default(0),
});

export const skill = pgTable("skill", {
  id: id(),
  categoryId: text("category_id").notNull().references(() => skillCategory.id, { onDelete: "restrict" }),
  parentId: text("parent_id"),
  name: text("name").notNull(),
  description: text("description").notNull().default(""),
  aliases: text("aliases").array().notNull().default([]),
  // draft | active | retired
  status: text("status").notNull().default("active"),
  sort: integer("sort").notNull().default(0),
  createdAt: created(),
}, (t) => [index("skill_category_idx").on(t.categoryId), index("skill_parent_idx").on(t.parentId)]);

export const proficiencyLevel = pgTable("proficiency_level", {
  level: integer("level").primaryKey(),
  name: text("name").notNull(),
  description: text("description").notNull().default(""),
});

// ---- what "good" looks like -----------------------------------------------------

export const roleSkill = pgTable("role_skill", {
  id: id(),
  roleId: text("role_id").notNull().references(() => jobRole.id, { onDelete: "cascade" }),
  // null = applies to every grade of the role; a grade-specific row wins over it
  gradeId: text("grade_id").references(() => grade.id, { onDelete: "cascade" }),
  skillId: text("skill_id").notNull().references(() => skill.id, { onDelete: "cascade" }),
  target: integer("target").notNull(),
  mandatory: boolean("mandatory").notNull().default(true),
}, (t) => [uniqueIndex("role_skill_uq").on(t.roleId, t.gradeId, t.skillId), index("role_skill_skill_idx").on(t.skillId)]);

// A team's demand: "this unit needs at least N people at level L in skill S".
export const unitRequirement = pgTable("unit_requirement", {
  id: id(),
  unitId: text("unit_id").notNull().references(() => orgUnit.id, { onDelete: "cascade" }),
  skillId: text("skill_id").notNull().references(() => skill.id, { onDelete: "cascade" }),
  minLevel: integer("min_level").notNull(),
  headcount: integer("headcount").notNull().default(1),
  note: text("note").notNull().default(""),
}, (t) => [uniqueIndex("unit_requirement_uq").on(t.unitId, t.skillId), index("unit_requirement_skill_idx").on(t.skillId)]);

// A manager's per-person required level. Wins over the role standard, and says so.
export const employeeTarget = pgTable("employee_target", {
  employeeId: text("employee_id").notNull().references(() => employee.id, { onDelete: "cascade" }),
  skillId: text("skill_id").notNull().references(() => skill.id, { onDelete: "cascade" }),
  target: integer("target").notNull(),
  reason: text("reason").notNull().default(""),
  setBy: text("set_by"),
  setAt: timestamp("set_at", { withTimezone: true }).defaultNow().notNull(),
}, (t) => [primaryKey({ columns: [t.employeeId, t.skillId] }), index("employee_target_skill_idx").on(t.skillId)]);

// ---- assessment -----------------------------------------------------------------

export const assessmentCycle = pgTable("assessment_cycle", {
  id: id(),
  name: text("name").notNull(),
  startsOn: date("starts_on").notNull(),
  dueOn: date("due_on").notNull(),
  // draft | open | closed
  status: text("status").notNull().default("draft"),
  createdAt: created(),
});

// The CURRENT state of one person's rating of one skill.
export const rating = pgTable("rating", {
  employeeId: text("employee_id").notNull().references(() => employee.id, { onDelete: "cascade" }),
  skillId: text("skill_id").notNull().references(() => skill.id, { onDelete: "cascade" }),
  selfLevel: integer("self_level"),
  selfComment: text("self_comment").notNull().default(""),
  selfAt: timestamp("self_at", { withTimezone: true }),
  validatedLevel: integer("validated_level"),
  validatedBy: text("validated_by"),
  validatedAt: timestamp("validated_at", { withTimezone: true }),
  evidence: text("evidence").notNull().default(""),
  managerComment: text("manager_comment").notNull().default(""),
  interest: boolean("interest").notNull().default(false),
  // draft (self saved) | submitted (awaiting manager) | validated | returned (sent back)
  status: text("status").notNull().default("draft"),
  cycleId: text("cycle_id"),
  lastUsedOn: date("last_used_on"),
}, (t) => [primaryKey({ columns: [t.employeeId, t.skillId] }), index("rating_status_idx").on(t.status), index("rating_skill_idx").on(t.skillId)]);

// Append-only history of every rating change (audit + trends).
export const ratingEvent = pgTable("rating_event", {
  id: id(),
  employeeId: text("employee_id").notNull(),
  skillId: text("skill_id").notNull(),
  // self | submit | validate | return | target
  kind: text("kind").notNull(),
  level: integer("level"),
  note: text("note").notNull().default(""),
  actorId: text("actor_id"),
  cycleId: text("cycle_id"),
  at: timestamp("at", { withTimezone: true }).defaultNow().notNull(),
}, (t) => [index("rating_event_emp_idx").on(t.employeeId, t.skillId), index("rating_event_at_idx").on(t.at)]);

// ---- closing the loop -----------------------------------------------------------

export const trainingPlan = pgTable("training_plan", {
  id: id(),
  employeeId: text("employee_id").notNull().references(() => employee.id, { onDelete: "cascade" }),
  skillId: text("skill_id").notNull().references(() => skill.id, { onDelete: "cascade" }),
  targetLevel: integer("target_level").notNull(),
  title: text("title").notNull(),
  link: text("link").notNull().default(""),
  dueOn: date("due_on"),
  // planned | in_progress | done | cancelled
  status: text("status").notNull().default("planned"),
  createdBy: text("created_by"),
  createdAt: created(),
}, (t) => [index("training_plan_emp_idx").on(t.employeeId), index("training_plan_skill_idx").on(t.skillId)]);

// Monthly roll-up per unit, so trends exist from day one and never need reconstructing.
export const snapshot = pgTable("snapshot", {
  unitId: text("unit_id").notNull(),
  period: text("period").notNull(), // YYYY-MM
  required: integer("required").notNull(),
  met: integer("met").notNull(),
  assessed: integer("assessed").notNull(),
  people: integer("people").notNull(),
  avgLevel: real("avg_level"),
  takenAt: timestamp("taken_at", { withTimezone: true }).defaultNow().notNull(),
}, (t) => [primaryKey({ columns: [t.unitId, t.period] })]);

// One row per directory sync (manual, scheduled or a dry run from the Test button).
export const syncRun = pgTable("sync_run", {
  id: id(),
  trigger: text("trigger").notNull(), // manual | schedule
  status: text("status").notNull().default("running"), // running | ok | failed
  startedAt: timestamp("started_at", { withTimezone: true }).defaultNow().notNull(),
  finishedAt: timestamp("finished_at", { withTimezone: true }),
  fetched: integer("fetched").notNull().default(0),
  created: integer("created").notNull().default(0),
  updated: integer("updated").notNull().default(0),
  deactivated: integer("deactivated").notNull().default(0),
  skipped: integer("skipped").notNull().default(0),
  message: text("message").notNull().default(""),
  actorName: text("actor_name").notNull().default(""),
}, (t) => [index("sync_run_started_idx").on(t.startedAt)]);

export const appSetting = pgTable("app_setting", {
  key: text("key").primaryKey(),
  value: jsonb("value").notNull(),
});

export const auditLog = pgTable("audit_log", {
  id: id(),
  at: timestamp("at", { withTimezone: true }).defaultNow().notNull(),
  actorId: text("actor_id"),
  actorName: text("actor_name").notNull().default(""),
  action: text("action").notNull(),
  entity: text("entity").notNull(),
  entityId: text("entity_id"),
  detail: jsonb("detail"),
}, (t) => [index("audit_log_at_idx").on(t.at)]);

// ---- scale: shared state for several app workers -------------------------------------

// Bumped by database triggers whenever data the engine reads changes (migration 0002), so
// every worker can keep its computed picture in memory and rebuild it only on change.
export const dataVersion = pgTable("data_version", {
  id: integer("id").primaryKey(),
  v: integer("v").notNull().default(0),
});

// A job (directory sync, scheduled backup, snapshot) runs in one worker at a time: the
// worker that holds the lease until it expires.
export const jobLease = pgTable("job_lease", {
  name: text("name").primaryKey(),
  holder: text("holder").notNull(),
  until: timestamp("until", { withTimezone: true }).notNull(),
});

// Single sign-on test captures (Admin › Single sign-on), shared by all workers.
export const ssoAttempt = pgTable("sso_attempt", {
  id: id(),
  at: timestamp("at", { withTimezone: true }).defaultNow().notNull(),
  payload: jsonb("payload").notNull(),
}, (t) => [index("sso_attempt_at_idx").on(t.at)]);

// The person a single sign-on was matched to, until the account is linked on first use.
export const ssoPending = pgTable("sso_pending", {
  email: text("email").primaryKey(),
  employeeId: text("employee_id").notNull(),
  at: timestamp("at", { withTimezone: true }).defaultNow().notNull(),
});

// ---- help and integrations --------------------------------------------------------------

// Feedback and contact requests from the Help page; handled in Admin › Feedback.
export const feedback = pgTable("feedback", {
  id: id(),
  at: timestamp("at", { withTimezone: true }).defaultNow().notNull(),
  userId: text("user_id"),
  name: text("name").notNull().default(""),
  email: text("email").notNull().default(""),
  // bug | data | idea | question | access | other
  kind: text("kind").notNull().default("question"),
  message: text("message").notNull(),
  page: text("page").notNull().default(""),
  // new | in_progress | done
  status: text("status").notNull().default("new"),
  adminNote: text("admin_note").notNull().default(""),
  handledBy: text("handled_by"),
  handledAt: timestamp("handled_at", { withTimezone: true }),
}, (t) => [index("feedback_at_idx").on(t.at), index("feedback_status_idx").on(t.status)]);

// Read-only reporting integrations (Power BI, Tableau, CSV) set up by an administrator.
// Only a hash of the key is stored; the key is shown once when it is created.
export const apiClient = pgTable("api_client", {
  id: id(),
  name: text("name").notNull(),
  // powerbi | tableau | csv | other
  tool: text("tool").notNull(),
  tokenHash: text("token_hash").notNull().unique(),
  tokenHint: text("token_hint").notNull(),
  datasets: jsonb("datasets").$type<string[]>().notNull(),
  createdBy: text("created_by").notNull().default(""),
  createdAt: created(),
  expiresAt: timestamp("expires_at", { withTimezone: true }),
  lastUsedAt: timestamp("last_used_at", { withTimezone: true }),
  useCount: integer("use_count").notNull().default(0),
  revokedAt: timestamp("revoked_at", { withTimezone: true }),
});
